-- The QAP live checklist's database (tools/conformance/qap/README.md):
-- the schemas and tables of qapd::testing (net/qapd/src/testing/sql/
-- fixtures.rs) on a real QS/400, for QS/400 Access's live tests.
-- RUNSQLSTM SRCSTMF('/home/QSECOFR/hlinv.sql') COMMIT(*NONE) NAMING(*SQL)
-- then the commands in hlinv.cl.

-- The schemas. CREATE SCHEMA journals each one's tables to its QSQJRN.
CREATE SCHEMA HLINV;
CREATE SCHEMA HLTEST;
CREATE SCHEMA HLPAY;
CREATE SCHEMA HLMANY;

-- HLINV.ASSETS: Navigator's sample, the twelve assets in service.
CREATE TABLE HLINV.ASSETS (
  ASSET_TAG CHAR(10) NOT NULL PRIMARY KEY,
  LOCATION CHAR(10) NOT NULL,
  MANUFACTURER FOR COLUMN MANUFACT VARCHAR(40) NOT NULL,
  MODEL VARCHAR(40) NOT NULL,
  SERIAL VARCHAR(40),
  ASSET_TYPE CHAR(12) NOT NULL,
  STATUS CHAR(8) NOT NULL,
  ACQUIRED DATE,
  COST DECIMAL(11, 2),
  RACK_U SMALLINT,
  NOTES VARCHAR(256),
  CHANGED_TS TIMESTAMP NOT NULL
);
LABEL ON TABLE HLINV.ASSETS IS 'Hardware assets';
LABEL ON COLUMN HLINV.ASSETS.ASSET_TAG IS 'Asset tag';
LABEL ON COLUMN HLINV.ASSETS.LOCATION IS 'Rack / site code';
LABEL ON COLUMN HLINV.ASSETS.MANUFACT IS 'Manufacturer';
LABEL ON COLUMN HLINV.ASSETS.MODEL IS 'Model';
LABEL ON COLUMN HLINV.ASSETS.SERIAL IS 'Serial number';
LABEL ON COLUMN HLINV.ASSETS.ASSET_TYPE IS 'Type code';
LABEL ON COLUMN HLINV.ASSETS.STATUS IS 'Status';
LABEL ON COLUMN HLINV.ASSETS.ACQUIRED IS 'Acquisition date';
LABEL ON COLUMN HLINV.ASSETS.COST IS 'Purchase cost';
LABEL ON COLUMN HLINV.ASSETS.RACK_U IS 'Rack unit position';
LABEL ON COLUMN HLINV.ASSETS.NOTES IS 'Short notes';
LABEL ON COLUMN HLINV.ASSETS.CHANGED_TS IS 'Last change';

CREATE TABLE HLINV.LOCATIONS (
  LOCATION CHAR(10) NOT NULL PRIMARY KEY,
  SITE VARCHAR(40) NOT NULL
);
LABEL ON TABLE HLINV.LOCATIONS IS 'Racks and sites';

-- A view: the assets in service.
CREATE VIEW HLINV.ASSETSACT AS SELECT * FROM HLINV.ASSETS WHERE STATUS = 'ACTIVE';
LABEL ON TABLE HLINV.ASSETSACT IS 'Assets in service';

-- HLTEST.ALLTYPES: one column of every type, as qapd::testing has it.
-- Six rows of values (DECFLOAT 1234.5678, 1.5E-30, Infinity, -Infinity,
-- NaN, sNaN), row 7 null but for its key. C_BITS is CCSID 65535.
CREATE TABLE HLTEST.ALLTYPES (
  ID INTEGER NOT NULL PRIMARY KEY,
  C_SMALLINT SMALLINT,
  C_INTEGER INTEGER,
  C_BIGINT BIGINT,
  C_DECIMAL DECIMAL(11, 2),
  C_NUMERIC NUMERIC(7, 3),
  C_DECFLOAT DECFLOAT(34),
  C_REAL REAL,
  C_DOUBLE DOUBLE,
  C_CHAR CHAR(10),
  C_VARCHAR VARCHAR(40),
  C_GRAPHIC GRAPHIC(5) CCSID 1200,
  C_VARGRAPHIC FOR COLUMN C_VARGRAPH VARGRAPHIC(20) CCSID 1200,
  C_CLOB CLOB(65536),
  C_BITS CHAR(8) FOR BIT DATA,
  C_BINARY BINARY(4),
  C_VARBINARY FOR COLUMN C_VARBIN VARBINARY(16),
  C_BLOB BLOB(65536),
  C_DATE DATE,
  C_TIME TIME,
  C_TS TIMESTAMP(6),
  C_TS12 TIMESTAMP(12),
  C_BOOLEAN BOOLEAN
);
LABEL ON TABLE HLTEST.ALLTYPES IS 'One column of every type';

-- Journaled (by the schema) and not (hlinv.cl ends NOJRN's journaling):
-- SQL7008 (55019) under commitment control.
CREATE TABLE HLTEST.JRN (ID INTEGER NOT NULL PRIMARY KEY, NAME VARCHAR(20));
LABEL ON TABLE HLTEST.JRN IS 'Journaled';
CREATE TABLE HLTEST.NOJRN (ID INTEGER NOT NULL PRIMARY KEY, NAME VARCHAR(20));
LABEL ON TABLE HLTEST.NOJRN IS 'Not journaled';

-- For cancel tests: 300 rows. This runs long, a row at a time (a join
-- would build its rows in the storage service's memory):
-- SELECT COUNT(*) FROM HLTEST.SLOW A WHERE EXISTS (SELECT 1 FROM HLTEST.SLOW B
--   WHERE EXISTS (SELECT 1 FROM HLTEST.SLOW C WHERE C.ID > A.ID + B.ID + 1000000))
CREATE TABLE HLTEST.SLOW (ID INTEGER NOT NULL PRIMARY KEY, NAME VARCHAR(20));
LABEL ON TABLE HLTEST.SLOW IS 'Three copies joined run long';
CREATE TABLE HLTEST.SLOWLOG (ID INTEGER NOT NULL PRIMARY KEY, NAME VARCHAR(20));
LABEL ON TABLE HLTEST.SLOWLOG IS 'Inserts for cancel tests';

-- Over a megabyte of rows: 1100 rows of 1000 characters.
CREATE TABLE HLTEST.BIG (ID INTEGER NOT NULL, DATA VARCHAR(1000) NOT NULL);
LABEL ON TABLE HLTEST.BIG IS 'Over a megabyte of rows';

-- HLPAY.SALARIES: hlinv.cl leaves it to ANN alone (SQL0551 for others).
CREATE TABLE HLPAY.SALARIES (EMPNO CHAR(6) NOT NULL, SALARY DECIMAL(9, 2) NOT NULL);
LABEL ON TABLE HLPAY.SALARIES IS 'Salaries';

